"""Read the vision contract: what the app sends, as generated by the app.

`generated/vision-contract.json` is written by `pnpm vision:export-contract` in `apps/app`, from the app's real
prompt builders. It is the ONLY source the `production` approach, the text modes and the pantry and recipe modes
take their prompts, schema and upload constraints from. There is no second copy in this package, and the file is
never edited by hand.

STALENESS. The contract carries the git blob hash of every app source file it was built from. When this checkout
also holds those files (the normal case, the eval lives in the same repository), `assert_fresh` hashes them and
refuses to run against a contract that no longer matches: an old contract would score a request nobody sends,
which is the failure this file exists to end. A checkout without the app sources (the eval copied out on its own)
cannot check and says so.
"""

from __future__ import annotations

import copy
import hashlib
import json
from dataclasses import dataclass, field
from pathlib import Path

DEFAULT_CONTRACT_PATH = "generated/vision-contract.json"
SUPPORTED_CONTRACT_VERSIONS = (1,)
REGENERATE_COMMAND = "cd apps/app && toolbox run -c ts-dev env CI=true pnpm vision:export-contract"

PHOTO_TASKS = ("plate_photo", "pantry_photo")
TEXT_TASKS = ("plate_text", "pantry_text")
RECIPE_TASK = "recipe"


class ContractError(SystemExit):
    """A contract problem that must stop a run before any request is made."""

    def __init__(self, message: str):
        super().__init__(f"ERROR: {message}")


def git_blob_sha1(data: bytes) -> str:
    """The id `git hash-object` prints for these bytes."""
    return hashlib.sha1(b"blob " + str(len(data)).encode("ascii") + b"\0" + data).hexdigest()


def find_repo_root(eval_root: Path) -> Path | None:
    """The repository root that holds the app sources the contract names, or None when this is not a full checkout."""
    for candidate in [eval_root.resolve(), *eval_root.resolve().parents]:
        if (candidate / "apps" / "app" / "app" / "services" / "vision" / "prompt.ts").is_file():
            return candidate
    return None


@dataclass
class Contract:
    data: dict
    path: Path
    freshness: dict = field(default_factory=lambda: {"checked": False, "reason": "not checked"})

    # -- lookups ----------------------------------------------------------

    @property
    def languages(self) -> list[str]:
        return list(self.data["languages"])

    @property
    def photo_constraints(self) -> dict:
        return self.data["photoConstraints"]

    def task(self, task_key: str) -> dict:
        tasks = self.data["tasks"]
        if task_key not in tasks:
            raise ContractError(f"unknown task {task_key!r}; the contract has {sorted(tasks)}")
        return tasks[task_key]

    def entry(self, task_key: str, language: str) -> dict:
        task = self.task(task_key)
        if language not in task["languages"]:
            raise ContractError(
                f"task {task_key!r} has no language {language!r}; the contract has {sorted(task['languages'])}"
            )
        return task["languages"][language]

    def schema(self, task_key: str) -> dict:
        return self.task(task_key)["jsonSchema"]

    def response_format(self, task_key: str) -> dict:
        task = self.task(task_key)
        return {
            "type": task["responseFormatType"],
            "json_schema": {
                "name": task["schemaName"],
                "strict": task["strict"],
                "schema": copy.deepcopy(task["jsonSchema"]),
            },
        }

    # -- messages ---------------------------------------------------------

    def build_messages(
        self,
        task_key: str,
        language: str,
        *,
        image_base64: str | None = None,
        input_text: str | None = None,
    ) -> list:
        """The chat messages for one call, laid out the way the app's request builder lays them out."""
        task = self.task(task_key)
        kind = task["inputKind"]
        entry = self.entry(task_key, language)
        markers = self.data["requestLayout"]["markers"]
        replacements = {markers["system"]: entry["systemPrompt"], markers["user"]: entry["userPrompt"]}
        if kind == "photo":
            if image_base64 is None:
                raise ContractError(f"task {task_key!r} reads a photo: image_base64 is required")
            replacements[markers["imageBase64"]] = image_base64
        else:
            if input_text is None:
                raise ContractError(f"task {task_key!r} reads text: input_text is required")
            replacements[markers["inputText"]] = input_text
        return _substitute(copy.deepcopy(self.data["requestLayout"]["messagesByInputKind"][kind]), replacements)

    def recipe_user_text(self, language: str, case: dict) -> str:
        """The recipe user text for one case, from the template the app's builder produced.

        `case` carries `slot`, `pantry` (a list of {name, amount, unit}) and `remaining_day_block`.
        """
        spec = self.data["recipeUserText"]
        markers = spec["markers"]
        for needed in ("slot", "pantry", "remaining_day_block"):
            if needed not in case:
                raise ContractError(f"recipe case {case.get('id', '?')!r} has no {needed!r}")
        lines = []
        for item in case["pantry"]:
            amount, unit = item.get("amount"), item.get("unit")
            if amount is None or unit is None:
                lines.append(spec["pantryLineWithoutAmount"].replace(markers["name"], str(item["name"])))
                continue
            lines.append(
                spec["pantryLineWithAmount"]
                .replace(markers["name"], str(item["name"]))
                .replace(markers["amount"], _format_amount(amount))
                .replace(markers["unit"], str(unit))
            )
        # The pantry lines go in LAST: an item name that contains a marker must not be substituted again.
        text = spec["template"]
        text = text.replace(markers["remainingDayBlock"], case["remaining_day_block"])
        text = text.replace(markers["slot"], str(case["slot"]))
        text = text.replace(markers["language"], language)
        return text.replace(markers["pantryLines"], "\n".join(lines))

    # -- freshness --------------------------------------------------------

    def stale_sources(self, repo_root: Path) -> list[str]:
        """The source files whose current hash is not the one the contract was generated from."""
        stale = []
        for rel_path, expected in self.data["generatedFrom"]["files"].items():
            source = repo_root / rel_path
            if not source.is_file():
                stale.append(f"{rel_path} (missing)")
            elif git_blob_sha1(source.read_bytes()) != expected:
                stale.append(rel_path)
        return stale


def _format_amount(amount) -> str:
    """JavaScript's `${number}`: 6 stays 6, 6.0 becomes 6, 0.5 stays 0.5."""
    if isinstance(amount, float) and amount.is_integer():
        return str(int(amount))
    return str(amount)


def _substitute(node, replacements: dict[str, str]):
    if isinstance(node, str):
        for marker, value in replacements.items():
            node = node.replace(marker, value)
        return node
    if isinstance(node, list):
        return [_substitute(item, replacements) for item in node]
    if isinstance(node, dict):
        return {key: _substitute(value, replacements) for key, value in node.items()}
    return node


def load_contract(path: Path) -> Contract:
    if not path.is_file():
        raise ContractError(f"vision contract not found: {path}\nGenerate it with: {REGENERATE_COMMAND}")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        raise ContractError(f"vision contract {path} is not valid JSON ({e}). Regenerate it: {REGENERATE_COMMAND}")
    version = data.get("contractVersion")
    if version not in SUPPORTED_CONTRACT_VERSIONS:
        raise ContractError(
            f"vision contract {path} is version {version!r}; this harness reads {SUPPORTED_CONTRACT_VERSIONS}"
        )
    return Contract(data=data, path=path)


def assert_fresh(contract: Contract, eval_root: Path, *, allow_stale: bool = False) -> Contract:
    """Stop the run when the contract is older than the app sources it was generated from."""
    repo_root = find_repo_root(eval_root)
    if repo_root is None:
        contract.freshness = {
            "checked": False,
            "reason": "the app sources are not in this checkout, so the contract could not be compared with them",
        }
        return contract
    stale = contract.stale_sources(repo_root)
    contract.freshness = {"checked": True, "stale": stale, "allowed_stale": bool(stale) and allow_stale}
    if stale and not allow_stale:
        raise ContractError(
            "the vision contract is STALE: these app sources changed after it was generated:\n  "
            + "\n  ".join(stale)
            + f"\nRegenerate it: {REGENERATE_COMMAND}\n(--allow-stale-contract runs it anyway and records that.)"
        )
    return contract
